setup:
MUTATE {
  CREATE CONCEPT ?alice { TYPE "Person" NAME "Alice" SET FIELDS {canonical_id: "urn:x:alice"} }
  CREATE CONCEPT ?dark { TYPE "Option" NAME "Dark" }
  ENSURE PROPOSITION ?p (?alice, "prefers", ?dark)
}

cases.command:
CREATE ASSERTION ?a {
  SET FIELDS { proposition: "P-1", asserted_by: "C-1", stance: "support", mode: "observed" }
  SET STRUCTURAL { ("evidence", :msg) {role: "support"} }
}
